package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SonarSettingsNativeTest {
 @Test public void strictPrivateConfigRoundtripRejectsWrongTypesWithoutChangingOtherPreferences()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());String name="sonar-settings-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(name,0);try{assertEquals(.05f,SonarSettings.read(prefs).gain,0);SonarSettings.save(prefs,new SonarConfig(.07f));String raw=prefs.getString("profile","");assertEquals(.07f,SonarSettings.read(prefs).gain,0);for(String bad:new String[]{raw.replace("48000","48000.5"),raw.replace("48000","\"48000\""),new org.json.JSONObject(raw).put("gain","0.07").toString(),raw.replace("fmcw_echo_change_v1","unknown"),raw.substring(0,raw.length()-1)+",\"extra\":true}"}){assertTrue(prefs.edit().putString("profile",bad).commit());assertThrows(IllegalStateException.class,()->SonarSettings.read(prefs));}assertTrue(prefs.edit().putString("profile",raw).commit());assertEquals(.07f,SonarSettings.read(prefs).gain,0);assertEquals(original,Prefs.of(c).getAll());}finally{c.deleteSharedPreferences(name);}}
}
